function r(n){if(n==null)return null;if(typeof n=="number")return new Date(n*1e3);if(typeof n=="string"&&n.length>0){const t=new Date(n);return isNaN(t.getTime())?null:t}return null}function e(n){if(n==null)return null;if(Array.isArray(n)&&n.length===3)return new Date(n[0],n[1]-1,n[2]);if(typeof n=="string"&&n.length>=8){const t=new Date(n);return isNaN(t.getTime())?null:t}return null}function i(n){if(n==null||n==="")return"N/A";const t=r(n);return!t||isNaN(t.getTime())?"N/A":t.toLocaleString("vi-VN")}function f(n){if(n==null||n==="")return"N/A";const t=e(n);return!t||isNaN(t.getTime())?"N/A":t.toLocaleDateString("vi-VN")}export{i as a,f};
